cat > /workspace/src/main.rs << 'EOF'
use clap::{Parser, ValueEnum};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;

mod args;
mod bytes_format;
mod data_tree;
mod hardlink;
mod json_data;
mod reporter;
mod tree_builder;
mod visualizer;

use args::Args;
use bytes_format::BytesFormat;
use data_tree::DataTree;
use json_data::JsonData;
use reporter::{report_error, ProgressReporter};
use tree_builder::TreeBuilder;
use visualizer::Visualizer;

fn main() {
    let args = Args::parse();

    if args.json_input {
        handle_json_input(&args);
    } else {
        handle_normal_operation(&args);
    }
}

fn handle_json_input(args: &Args) {
    use std::io::Read;
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).expect("Failed to read JSON from stdin");

    let json_data: JsonData = serde_json::from_str(&input).expect("Failed to parse JSON");
    let tree = json_data.to_tree();

    if args.json_output {
        let output = serde_json::to_string(&json_data).expect("Failed to serialize JSON");
        println!("{}", output);
    } else {
        let visualizer = Visualizer::new(args);
        visualizer.display_tree(&tree);
    }
}

fn handle_normal_operation(args: &Args) {
    let files = if args.files.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.files.clone()
    };

    let mut builder = TreeBuilder::new(args);
    let tree = builder.build(&files);

    if args.json_output {
        let json_data = JsonData::from_tree(&tree, args);
        let output = serde_json::to_string(&json_data).expect("Failed to serialize JSON");
        println!("{}", output);
    } else {
        let visualizer = Visualizer::new(args);
        visualizer.display_tree(&tree);
    }
}
EOF

