cat > /workspace/src/args.rs << 'EOF'
use clap::{Parser, ValueEnum};
use std::path::PathBuf;

#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum BytesFormatType {
    #[value(name = "plain")]
    Plain,
    #[value(name = "metric")]
    Metric,
    #[value(name = "binary")]
    Binary,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum QuantityType {
    #[value(name = "apparent-size")]
    ApparentSize,
    #[value(name = "block-size")]
    BlockSize,
    #[value(name = "block-count")]
    BlockCount,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum ThreadsType {
    #[value(name = "auto")]
    Auto,
    #[value(name = "max")]
    Max,
}

#[derive(Parser, Debug)]
#[command(name = "pdu")]
#[command(about = "Summarize disk usage of the set of files, recursively for directories.", long_about = None)]
#[command(version = "0.21.1")]
pub struct Args {
    /// List of files and/or directories
    #[arg(value_name = "FILES")]
    pub files: Vec<PathBuf>,

    /// Read JSON data from stdin
    #[arg(long)]
    pub json_input: bool,

    /// Print JSON data instead of an ASCII chart
    #[arg(long)]
    pub json_output: bool,

    /// How to display the numbers of bytes
    #[arg(short = 'b', long, value_name = "BYTES_FORMAT", default_value = "metric")]
    pub bytes_format: BytesFormatType,

    /// Detect and subtract the sizes of hardlinks from their parent directory totals
    #[arg(short = 'H', long, aliases = &["detect-links", "dedupe-links"])]
    pub deduplicate_hardlinks: bool,

    /// Print the tree top-down instead of bottom-up
    #[arg(long)]
    pub top_down: bool,

    /// Set the root of the bars to the right
    #[arg(long)]
    pub align_right: bool,

    /// Aspect of the files/directories to be measured
    #[arg(short = 'q', long, value_name = "QUANTITY", default_value = "block-size")]
    pub quantity: QuantityType,

    /// Maximum depth to display the data
    #[arg(short = 'd', long, value_name = "MAX_DEPTH", default_value = "10", aliases = &["depth"])]
    pub max_depth: String,

    /// Width of the visualization
    #[arg(short = 'w', long, value_name = "TOTAL_WIDTH", aliases = &["width"])]
    pub total_width: Option<usize>,

    /// Maximum widths of the tree column and width of the bar column
    #[arg(long, value_names = &["TREE_WIDTH", "BAR_WIDTH"], num_args = 2)]
    pub column_width: Option<Vec<usize>>,

    /// Minimal size proportion required to appear
    #[arg(short = 'm', long, value_name = "MIN_RATIO", default_value = "0.01")]
    pub min_ratio: f64,

    /// Do not sort the branches in the tree
    #[arg(long)]
    pub no_sort: bool,

    /// Prevent filesystem error messages from appearing in stderr
    #[arg(short = 's', long, aliases = &["no-errors"])]
    pub silent_errors: bool,

    /// Report progress being made at the expense of performance
    #[arg(short = 'p', long)]
    pub progress: bool,

    /// Set the maximum number of threads to spawn
    #[arg(long, value_name = "THREADS", default_value = "auto")]
    pub threads: String,

    /// Do not output `.shared.details` in the JSON output
    #[arg(long)]
    pub omit_json_shared_details: bool,

    /// Do not output `.shared.summary` in the JSON output
    #[arg(long)]
    pub omit_json_shared_summary: bool,
}

impl Args {
    pub fn get_max_depth(&self) -> Option<usize> {
        if self.max_depth == "inf" {
            None
        } else {
            self.max_depth.parse().ok()
        }
    }

    pub fn get_thread_count(&self) -> usize {
        match self.threads.as_str() {
            "auto" => num_cpus::get(),
            "max" => num_cpus::get_physical(),
            _ => self.threads.parse().unwrap_or(num_cpus::get()),
        }
    }
}
EOF

