use crate::args::BytesFormatType;

pub struct BytesFormatter {
    format_type: BytesFormatType,
}

impl BytesFormatter {
    pub fn new(format_type: BytesFormatType) -> Self {
        BytesFormatter { format_type }
    }

    pub fn format(&self, bytes: u64) -> String {
        match self.format_type {
            BytesFormatType::Plain => bytes.to_string(),
            BytesFormatType::Metric => self.format_metric(bytes),
            BytesFormatType::Binary => self.format_binary(bytes),
        }
    }

    fn format_metric(&self, bytes: u64) -> String {
        const UNITS: &[&str] = &["B", "K", "M", "G", "T", "P"];
        self.format_with_divisor(bytes, 1000, UNITS)
    }

    fn format_binary(&self, bytes: u64) -> String {
        const UNITS: &[&str] = &["B", "K", "M", "G", "T", "P"];
        self.format_with_divisor(bytes, 1024, UNITS)
    }

