use std::collections::HashMap;
use std::path::PathBuf;

pub struct HardlinkDetector {
    inode_map: HashMap<(u64, u64), Vec<PathBuf>>,
}

impl HardlinkDetector {
    pub fn new() -> Self {
        HardlinkDetector {
            inode_map: HashMap::new(),
        }
    }

    pub fn add(&mut self, path: PathBuf, ino: u64, dev: u64) {
        self.inode_map
            .entry((dev, ino))
            .or_insert_with(Vec::new)
            .push(path);
    }

    pub fn get_hardlinks(&self) -> Vec<Vec<PathBuf>> {
        self.inode_map
            .values()
            .filter(|paths| paths.len() > 1)
            .cloned()
            .collect()
    }
}
