use crate::args::Args;
use crate::bytes_format::BytesFormatter;
use crate::data_tree::DataTree;
use termsize::get;

pub struct Visualizer<'a> {
    args: &'a Args,
    formatter: BytesFormatter,
}

impl<'a> Visualizer<'a> {
    pub fn new(args: &'a Args) -> Self {
        Visualizer {
            args,
            formatter: BytesFormatter::new(args.bytes_format),
        }
    }

    pub fn display_tree(&self, tree: &DataTree) {
        println!();
        println!();

        if self.args.top_down {
            self.display_tree_top_down(tree, 0, &tree.size, "", true);
        } else {
            self.display_tree_bottom_up(tree, 0, &tree.size, "", true);
        }
    }

    fn display_tree_bottom_up(&self, tree: &DataTree, depth: usize, root_size: &u64, prefix: &str, is_last: bool) {
        if let Some(max_depth) = self.args.get_max_depth() {
            if depth > max_depth {
                return;
            }
        }

        let connector = if is_last { "└─" } else { "├─" };
        let continuation = if is_last { "  " } else { "│ " };

        self.print_node(tree, root_size, prefix, connector);

        for (i, child) in tree.children.iter().enumerate() {
            let is_last_child = i == tree.children.len() - 1;
            let new_prefix = if depth == 0 {
                if is_last_child {
                    format!("{} ", " ".repeat(prefix.len()))
                } else {
                    format!("{}│ ", " ".repeat(prefix.len()))
                }
            } else {
                format!("{}{}", prefix, continuation)
            };

            self.display_tree_bottom_up(child, depth + 1, root_size, &new_prefix, is_last_child);
        }
    }

    fn display_tree_top_down(&self, tree: &DataTree, depth: usize, root_size: &u64, prefix: &str, is_root: bool) {
        if let Some(max_depth) = self.args.get_max_depth() {
            if depth > max_depth {
                return;
            }
        }

        self.print_node(tree, root_size, "", if is_root { "┌─" } else { "├─" });

        for (i, child) in tree.children.iter().enumerate() {
            let is_last_child = i == tree.children.len() - 1;
            let connector = if is_last_child { "└─" } else { "├─" };
            let new_prefix = if is_root { "  " } else { "│ " };

            self.display_tree_top_down(child, depth + 1, root_size, &new_prefix, false);
        }
    }

    fn print_node(&self, tree: &DataTree, root_size: &u64, prefix: &str, connector: &str) {
        let formatted_size = self.formatter.format(tree.size);
        let percentage = if *root_size > 0 {
            (tree.size as f64 / *root_size as f64) * 100.0
        } else {
            0.0
        };

        let bar_width = self.get_bar_width();
        let bar_filled = ((tree.size as f64 / *root_size as f64) * bar_width as f64) as usize;
        let bar_empty = bar_width.saturating_sub(bar_filled);

        let filled_char = "█";
        let empty_char = "░";

        let bar = format!(
            "{}{}",
            filled_char.repeat(bar_filled),
            empty_char.repeat(bar_empty)
        );

        println!(
            "{:>5} {}{:<20}│{}│{:>4}%",
            formatted_size, prefix, connector, bar, percentage as u32
        );
    }

    fn get_bar_width(&self) -> usize {
        if let Some(width) = self.args.total_width {
            width.saturating_sub(40)
        } else if let Some((_, bar_width)) = self.args.column_width.as_ref().map(|cw| (cw[0], cw[1])) {
            bar_width
        } else {
            120
        }
    }
}
