#[derive(Debug, Clone)]
pub struct DataTree {
    pub name: String,
    pub size: u64,
    pub children: Vec<DataTree>,
}

impl DataTree {
    pub fn new(name: String, size: u64, children: Vec<DataTree>) -> Self {
        DataTree {
            name,
            size,
            children,
        }
    }

    pub fn sort_children(&mut self, do_sort: bool) {
        if do_sort {
            self.children.sort_by(|a, b| b.size.cmp(&a.size));
        }
        for child in &mut self.children {
            child.sort_children(do_sort);
        }
    }

    pub fn apply_min_ratio(&mut self, ratio: f64) {
        let total = self.size;
        self.apply_min_ratio_recursive(ratio, total);
    }

    fn apply_min_ratio_recursive(&mut self, ratio: f64, total: u64) {
        let threshold = (total as f64 * ratio) as u64;
        self.children.retain(|child| child.size >= threshold);
        for child in &mut self.children {
            child.apply_min_ratio_recursive(ratio, total);
        }
    }

    pub fn apply_max_depth(&mut self, depth: usize) {
        self.apply_max_depth_recursive(0, depth);
    }

    fn apply_max_depth_recursive(&mut self, current_depth: usize, max_depth: usize) {
        if current_depth >= max_depth {
            self.children.clear();
        } else {
            for child in &mut self.children {
                child.apply_max_depth_recursive(current_depth + 1, max_depth);
            }
        }
    }

    pub fn total_size(&self) -> u64 {
        self.size
    }
}
