pub struct BytesFormatter {
    format_type: String,
}

impl BytesFormatter {
    pub fn new(format_type: String) -> Self {
        BytesFormatter { format_type }
    }

    pub fn format(&self, bytes: u64) -> String {
        match self.format_type.as_str() {
            "plain" => bytes.to_string(),
            "binary" => self.format_binary(bytes),
            _ => self.format_metric(bytes),
        }
    }

    fn format_metric(&self, bytes: u64) -> String {
        const UNITS: &[&str] = &["B", "K", "M", "G", "T", "P"];
        self.format_with_divisor(bytes, 1000, UNITS)
    }

    fn format_binary(&self, bytes: u64) -> String {
        const UNITS: &[&str] = &["B", "K", "M", "G", "T", "P"];
        self.format_with_divisor(bytes, 1024, UNITS)
    }

    fn format_with_divisor(&self, bytes: u64, divisor: u64, units: &[&str]) -> String {
        let mut value = bytes as f64;
        let mut unit_idx = 0;

        while value >= divisor as f64 && unit_idx < units.len() - 1 {
            value /= divisor as f64;
            unit_idx += 1;
        }

        let unit = units[unit_idx];
        if unit_idx == 0 {
            format!("{:.0}{}", value, unit)
        } else {
            format!("{:.1}{}", value, unit)
        }
    }
}
