    Ok(parsed)
}

pub fn tree_to_json(tree: &DataTree) -> String {
    let mut result = String::from("{");
    result.push_str("\"schema-version\":\"2024-11-02\",");
    result.push_str("\"pdu\":\"0.21.1\",");
    result.push_str("\"unit\":\"bytes\",");
    result.push_str("\"tree\":");
    result.push_str(&tree_to_json_recursive(tree));
    result.push('}');
    result
}

fn tree_to_json_recursive(tree: &DataTree) -> String {
    let mut result = String::from("{");
    result.push_str(&format!("\"name\":\"{}\",", escape_json_string(&tree.name)));
    result.push_str(&format!("\"size\":{},", tree.size));
    result.push_str("\"children\":[");

    for (i, child) in tree.children.iter().enumerate() {
        if i > 0 {
            result.push(',');
        }
        result.push_str(&tree_to_json_recursive(child));
    }

    result.push_str("]}");
    result
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}

fn parse_json_object(input: &str) -> Result<DataTree, String> {
    let trimmed = input.trim();
    if !trimmed.starts_with('{') {
        return Err("Invalid JSON: expected object".to_string());
    }

    // Find "tree" field
    let tree_start = match trimmed.find("\"tree\":") {
        Some(pos) => pos + 7,
        None => return Err("Invalid JSON: no tree field".to_string()),
    };

    let tree_str = &trimmed[tree_start..];
    parse_tree_object(tree_str)
}

fn parse_tree_object(input: &str) -> Result<DataTree, String> {
    let trimmed = input.trim_start();
    if !trimmed.starts_with('{') {
        return Err("Invalid JSON: expected object".to_string());
    }

    let mut name = String::new();
    let mut size = 0u64;
    let mut children = Vec::new();

    let mut depth = 0;
    let mut in_string = false;
    let mut escape_next = false;
    let mut current_key = String::new();
    let mut current_value = String::new();
    let mut parsing_key = true;

    for (i, ch) in trimmed.chars().enumerate() {
        if escape_next {
            escape_next = false;
            current_value.push(ch);
            continue;
        }

        if ch == '\\' && in_string {
            escape_next = true;
            current_value.push(ch);
            continue;
        }

        if ch == '"' {
            in_string = !in_string;
            if !in_string && parsing_key && !current_key.is_empty() {
                // Key parsed
                parsing_key = false;
            }
            if !parsing_key {
                current_value.push(ch);
            } else {
                current_key.push(ch);
            }
            continue;
        }

        if in_string {
            if parsing_key {
                current_key.push(ch);
            } else {
                current_value.push(ch);
            }
            continue;
        }

        match ch {
            ':' if !parsing_key => {
                // Skip colon after key
            }
            ',' | '}' => {
                if !current_key.is_empty() && !current_value.is_empty() {
                    let key = clean_key(&current_key);
                    match key.as_str() {
                        "name" => name = clean_value(&current_value),
                        "size" => size = parse_u64(&current_value).unwrap_or(0),
                        "children" => {
