                            }
                        }
                        _ => {}
                    }
                }
                current_key.clear();
                current_value.clear();
                parsing_key = true;

                if ch == '}' {
                    break;
                }
            }
            '{' => {
                depth += 1;
                if !parsing_key {
                    current_value.push(ch);
                }
            }
            '[' => {
                if !parsing_key {
                    current_value.push(ch);
                }
            }
            ']' | '}' => {
                if depth > 0 {
                    depth -= 1;
                    if !parsing_key {
                        current_value.push(ch);
                    }
                }
            }
            _ => {
                if !parsing_key {
                    current_value.push(ch);
                }
            }
        }
    }

    Ok(DataTree::new(name, size, children))
}

fn clean_key(key: &str) -> String {
    key.trim().trim_matches('"').to_string()
}

fn clean_value(value: &str) -> String {
    value.trim().trim_matches('"').trim_matches('[').trim_matches(']').to_string()
}

fn parse_u64(s: &str) -> Option<u64> {
    s.trim().parse().ok()
}

fn parse_children_array(input: &str) -> Result<Vec<DataTree>, String> {
    let trimmed = input.trim();
    if !trimmed.starts_with('[') {
        return Ok(Vec::new());
    }

    let mut children = Vec::new();
    let mut depth = 0;
    let mut current_obj = String::new();

    for ch in trimmed[1..].chars() {
        match ch {
            '{' => {
                depth += 1;
                current_obj.push(ch);
            }
            '}' => {
                current_obj.push(ch);
                depth -= 1;
                if depth == 0 && !current_obj.is_empty() {
                    if let Ok(child) = parse_tree_object(&current_obj) {
                        children.push(child);
                    }
                    current_obj.clear();
                }
            }
            '[' if depth == 0 => break,
            _ if depth > 0 => {
                current_obj.push(ch);
            }
            _ => {}
        }
    }

    Ok(children)
}
