use crate::args::Args;
use crate::formatter::BytesFormatter;
use crate::tree::DataTree;

pub struct Visualizer<'a> {
    args: &'a Args,
    formatter: BytesFormatter,
}

impl<'a> Visualizer<'a> {
    pub fn new(args: &'a Args) -> Self {
        Visualizer {
            args,
            formatter: BytesFormatter::new(args.bytes_format.clone()),
        }
    }

    pub fn display_tree(&self, tree: &DataTree) {
        if self.args.top_down {
            self.display_tree_top_down(tree, 0, tree.size, "", true);
        } else {
            self.display_tree_bottom_up(tree, 0, tree.size, "", true);
        }
    }

    fn display_tree_bottom_up(&self, tree: &DataTree, _depth: usize, root_size: u64, _prefix: &str, is_root: bool) {
        if let Some(max_depth) = self.args.get_max_depth() {
            if _depth > max_depth {
                return;
            }
        }

        self.print_node(tree, root_size, "", if is_root { "┌─" } else { "├─" });

        for (i, child) in tree.children.iter().enumerate() {
            let is_last = i == tree.children.len() - 1;
            let connector = if is_last { "┴" } else { "┤" };
            let prefix = if is_last { "  " } else { "│ " };
            self.display_tree_bottom_up(child, _depth + 1, root_size, prefix, false);
        }
    }

    fn display_tree_top_down(&self, tree: &DataTree, _depth: usize, root_size: u64, _prefix: &str, is_root: bool) {
        if let Some(max_depth) = self.args.get_max_depth() {
            if _depth > max_depth {
                return;
            }
        }

        self.print_node(tree, root_size, "", if is_root { "┌─" } else { "├─" });

        for (i, child) in tree.children.iter().enumerate() {
            let is_last = i == tree.children.len() - 1;
            let _connector = if is_last { "└─" } else { "├─" };
            self.display_tree_top_down(child, _depth + 1, root_size, "", false);
        }
    }

    fn print_node(&self, tree: &DataTree, root_size: u64, _prefix: &str, connector: &str) {
        let formatted_size = self.formatter.format(tree.size);
        let percentage = if root_size > 0 {
            (tree.size as f64 / root_size as f64) * 100.0
        } else {
            0.0
        };

        let bar_width = self.get_bar_width();
        let bar_filled = if root_size > 0 {
            ((tree.size as f64 / root_size as f64) * bar_width as f64) as usize
        } else {
            0
        };
        let bar_empty = bar_width.saturating_sub(bar_filled);

        let bar = format!(
            "{}{}",
            "█".repeat(bar_filled),
            "░".repeat(bar_empty)
        );

        let name_part = format!("{}{:<20}", connector, tree.name);
        println!(
            "{:>5} {:<20}│{}│{:>4}%",
            formatted_size, name_part, bar, percentage as u32
        );
    }

    fn get_bar_width(&self) -> usize {
        if let Some(width) = self.args.total_width {
            width.saturating_sub(40)
        } else if let Some((_, bar_width)) = self.args.column_width {
            bar_width
        } else {
            120
        }
    }
}
