use crate::tree::DataTree;

pub fn parse_json_input(input: &str) -> Result<DataTree, String> {
    let trimmed = input.trim();

    // Find the tree object
    if let Some(tree_pos) = trimmed.find("\"tree\":") {
        let tree_str = &trimmed[tree_pos + 7..].trim_start();
        if tree_str.starts_with('{') {
            return parse_tree_object(tree_str);
        }
    }

    Err("Failed to find tree in JSON".to_string())
}

pub fn tree_to_json(tree: &DataTree) -> String {
    let mut result = String::from("{");
    result.push_str("\"schema-version\":\"2024-11-02\",");
    result.push_str("\"pdu\":\"0.21.1\",");
    result.push_str("\"unit\":\"bytes\",");
    result.push_str("\"tree\":");
    result.push_str(&tree_to_json_recursive(tree));
    result.push('}');
    result
}

fn tree_to_json_recursive(tree: &DataTree) -> String {
    let mut result = String::from("{");
    result.push_str(&format!("\"name\":\"{}\",", escape_json_string(&tree.name)));
    result.push_str(&format!("\"size\":{},", tree.size));
    result.push_str("\"children\":[");

    for (i, child) in tree.children.iter().enumerate() {
        if i > 0 {
            result.push(',');
        }
        result.push_str(&tree_to_json_recursive(child));
    }

    result.push_str("]}");
    result
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}

fn parse_tree_object(input: &str) -> Result<DataTree, String> {
    let mut name = String::new();
    let mut size = 0u64;
    let mut children = Vec::new();

    let mut i = 0;
    let chars: Vec<char> = input.chars().collect();

    // Skip opening {
    if chars.get(0) != Some(&'{') {
        return Err("Expected {".to_string());
    }
    i = 1;

    let mut in_string = false;
    let mut escape = false;
    let mut current_key = String::new();
    let mut current_value = String::new();
    let mut parsing_key = true;
    let mut depth = 0;

    while i < chars.len() {
        let ch = chars[i];

        // Handle escape sequences
        if escape {
            current_value.push(ch);
            escape = false;
            i += 1;
            continue;
        }

        if ch == '\\' && in_string {
            escape = true;
            current_value.push(ch);
            i += 1;
            continue;
        }

        // Handle quotes
        if ch == '"' {
            in_string = !in_string;
            if parsing_key && !in_string {
                // End of key
                parsing_key = false;
            } else if !parsing_key && in_string {
                // Start of value
                current_value.clear();
            }
            if !in_string && parsing_key {
                current_key.push(ch);
            } else if parsing_key {
                current_key.push(ch);
            } else if in_string || !parsing_key {
                current_value.push(ch);
            }
            i += 1;
            continue;
        }

        if in_string {
            current_value.push(ch);
            i += 1;
            continue;
        }

        // Parse structure
        match ch {
            ':' if !parsing_key => {
                // Skip colon after key
            }
            ',' | '}' => {
                if !current_key.is_empty() {
                    let key = current_key.trim_matches('"');
                    match key {
                        "name" => name = current_value.trim_matches('"').to_string(),
                        "size" => size = current_value.parse().unwrap_or(0),
                        "children" => {
                            // Skip the array and let the next iteration handle it
                            children = parse_children_array(&current_value)?;
                        }
                        _ => {}
                    }
                }
                current_key.clear();
                current_value.clear();
                parsing_key = true;

                if ch == '}' {
                    break;
                }
            }
            '{' => {
                depth += 1;
                current_value.push(ch);
            }
            '[' => {
                current_value.push(ch);
            }
            ']' => {
                current_value.push(ch);
            }
            _ if !current_key.is_empty() && !parsing_key => {
                current_value.push(ch);
            }
            _ => {}
        }

        i += 1;
    }

    Ok(DataTree::new(name, size, children))
}

fn parse_children_array(input: &str) -> Result<Vec<DataTree>, String> {
    let trimmed = input.trim();
    if !trimmed.starts_with('[') {
        return Ok(Vec::new());
    }

    let mut children = Vec::new();
    let mut depth = 0;
    let mut current_obj = String::new();
    let mut in_string = false;
    let mut escape = false;

    for ch in trimmed[1..].chars() {
        // Handle strings
        if escape {
            current_obj.push(ch);
            escape = false;
            continue;
        }

        if ch == '\\' && in_string {
            escape = true;
            current_obj.push(ch);
            continue;
        }

        if ch == '"' {
            in_string = !in_string;
            current_obj.push(ch);
            continue;
        }

        if in_string {
            current_obj.push(ch);
            continue;
        }

        // Parse objects
        match ch {
            '{' => {
                depth += 1;
                current_obj.push(ch);
            }
            '}' => {
                current_obj.push(ch);
                depth -= 1;
                if depth == 0 && !current_obj.is_empty() {
                    if let Ok(child) = parse_tree_object(&current_obj) {
                        children.push(child);
                    }
                    current_obj.clear();
                }
            }
            ']' if depth == 0 => break,
            _ if depth > 0 => {
                current_obj.push(ch);
            }
            _ => {}
        }
    }

    Ok(children)
}
