            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}

enum JsonValue {
    Object(std::collections::HashMap<String, JsonValue>),
    Array(Vec<JsonValue>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

fn parse_json_value(input: &str) -> Result<(JsonValue, usize), String> {
    let trimmed = skip_whitespace(input, 0);
    if trimmed >= input.len() {
        return Err("Unexpected end of input".to_string());
    }

    let c = input.chars().nth(trimmed).unwrap();

    match c {
        '{' => parse_json_object(input, trimmed + 1),
        '[' => parse_json_array(input, trimmed + 1),
        '"' => parse_json_string(input, trimmed + 1),
        't' | 'f' => parse_json_bool(input, trimmed),
        'n' => parse_json_null(input, trimmed),
        '-' | '0'..='9' => parse_json_number(input, trimmed),
        _ => Err(format!("Unexpected character: {}", c)),
    }
}

fn parse_json_object(input: &str, mut pos: usize) -> Result<(JsonValue, usize), String> {
    let mut map = std::collections::HashMap::new();
    pos = skip_whitespace(input, pos);

    if input.chars().nth(pos) == Some('}') {
        return Ok((JsonValue::Object(map), pos + 1));
    }

    loop {
        pos = skip_whitespace(input, pos);

        // Parse key
        if input.chars().nth(pos) != Some('"') {
            return Err("Expected string key".to_string());
        }
        pos += 1;

        let (key_val, new_pos) = parse_json_string_content(input, pos)?;
        pos = new_pos;
        let key = match key_val {
            JsonValue::String(s) => s,
            _ => return Err("Key is not a string".to_string()),
        };

        pos = skip_whitespace(input, pos);
        if input.chars().nth(pos) != Some(':') {
            return Err("Expected colon".to_string());
        }
        pos += 1;

        // Parse value
        pos = skip_whitespace(input, pos);
        let (value, new_pos) = parse_json_value(input, pos)?;
        pos = new_pos;

        map.insert(key, value);

        pos = skip_whitespace(input, pos);
        let c = input.chars().nth(pos);

        if c == Some('}') {
            return Ok((JsonValue::Object(map), pos + 1));
        } else if c == Some(',') {
            pos += 1;
        } else {
            return Err("Expected comma or }".to_string());
        }
    }
}

fn parse_json_array(input: &str, mut pos: usize) -> Result<(JsonValue, usize), String> {
    let mut arr = Vec::new();
    pos = skip_whitespace(input, pos);

    if input.chars().nth(pos) == Some(']') {
        return Ok((JsonValue::Array(arr), pos + 1));
    }

    loop {
        pos = skip_whitespace(input, pos);
        let (value, new_pos) = parse_json_value(input, pos)?;
        pos = new_pos;
        arr.push(value);

        pos = skip_whitespace(input, pos);
        let c = input.chars().nth(pos);

        if c == Some(']') {
            return Ok((JsonValue::Array(arr), pos + 1));
        } else if c == Some(',') {
            pos += 1;
        } else {
            return Err("Expected comma or ]".to_string());
        }
    }
}

fn parse_json_string(input: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let (s, new_pos) = parse_json_string_content(input, pos)?;
    Ok((s, new_pos))
}

fn parse_json_string_content(input: &str, mut pos: usize) -> Result<(JsonValue, usize), String> {
    let mut s = String::new();

    loop {
        if pos >= input.len() {
            return Err("Unterminated string".to_string());
        }

        let c = input.chars().nth(pos).unwrap();

        if c == '"' {
            return Ok((JsonValue::String(s), pos + 1));
        } else if c == '\\' {
            pos += 1;
            if pos >= input.len() {
                return Err("Unterminated escape sequence".to_string());
            }
            let escaped = input.chars().nth(pos).unwrap();
            let unescaped = match escaped {
                '"' => '"',
                '\\' => '\\',
                '/' => '/',
                'b' => '\x08',
                'f' => '\x0c',
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                'u' => {
                    // Unicode escape - simplified
                    pos += 4;
                    '?'
                }
                _ => escaped,
            };
            s.push(unescaped);
        } else {
            s.push(c);
        }

        pos += 1;
    }
}

fn parse_json_number(input: &str, mut pos: usize) -> Result<(JsonValue, usize), String> {
    let start = pos;

    if input.chars().nth(pos) == Some('-') {
        pos += 1;
    }

    while let Some(c) = input.chars().nth(pos) {
        if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
            pos += 1;
        } else {
            break;
        }
    }

    let num_str = &input[start..pos];
    let num: f64 = num_str.parse().map_err(|_| "Invalid number".to_string())?;
    Ok((JsonValue::Number(num), pos))
}

fn parse_json_bool(input: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    if input[pos..].starts_with("true") {
        Ok((JsonValue::Bool(true), pos + 4))
    } else if input[pos..].starts_with("false") {
        Ok((JsonValue::Bool(false), pos + 5))
    } else {
        Err("Invalid boolean".to_string())
    }
}

fn parse_json_null(input: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    if input[pos..].starts_with("null") {
        Ok((JsonValue::Null, pos + 4))
    } else {
        Err("Invalid null".to_string())
    }
}

fn skip_whitespace(input: &str, mut pos: usize) -> usize {
    while let Some(c) = input.chars().nth(pos) {
        if c.is_whitespace() {
            pos += 1;
        } else {
            break;
        }
    }
    pos
}

fn json_object_to_tree(obj: &std::collections::HashMap<String, JsonValue>) -> DataTree {
    let name = match obj.get("name") {
        Some(JsonValue::String(s)) => s.clone(),
        _ => String::new(),
    };

    let size = match obj.get("size") {
        Some(JsonValue::Number(n)) => *n as u64,
        _ => 0,
    };

    let children = match obj.get("children") {
        Some(JsonValue::Array(arr)) => {
            arr.iter()
                .filter_map(|val| {
                    if let JsonValue::Object(child_obj) = val {
                        Some(json_object_to_tree(child_obj))
                    } else {
                        None
                    }
                })
                .collect()
        }
        _ => Vec::new(),
    };

    DataTree::new(name, size, children)
}
