use crate::args::Args;
use crate::formatter::BytesFormatter;
use crate::tree::DataTree;

pub struct Visualizer<'a> {
    args: &'a Args,
    formatter: BytesFormatter,
}

impl<'a> Visualizer<'a> {
    pub fn new(args: &'a Args) -> Self {
        Visualizer {
            args,
            formatter: BytesFormatter::new(args.bytes_format.clone()),
        }
    }

    pub fn display_tree(&self, tree: &DataTree) {
        if self.args.top_down {
            self.display_top_down(tree, 0, tree.size, "");
        } else {
            // Bottom-up display
            self.display_bottom_up(tree, 0, tree.size, "");
        }
    }

    fn display_bottom_up(&self, tree: &DataTree, depth: usize, root_size: u64, prefix: &str) {
        if let Some(max_depth) = self.args.get_max_depth() {
            if depth > max_depth {
                return;
            }
        }

        // First, recursively display all children (bottom-up)
        for (i, child) in tree.children.iter().enumerate() {
            let is_last_child = i == tree.children.len() - 1;
            let child_connector = if is_last_child { "┴" } else { "├" };
            let child_prefix = if depth == 0 {
                String::new()
            } else {
                format!("{}│ ", prefix)
            };
            self.display_bottom_up(child, depth + 1, root_size, &child_prefix);
        }

        // Then display this node
        self.print_node_bottom_up(tree, root_size, prefix, depth);
    }

    fn display_top_down(&self, tree: &DataTree, depth: usize, root_size: u64, prefix: &str) {
        if let Some(max_depth) = self.args.get_max_depth() {
            if depth > max_depth {
                return;
            }
        }

        // First display this node
        self.print_node_top_down(tree, root_size, prefix, depth);

        // Then display children
        for (i, child) in tree.children.iter().enumerate() {
            let is_last_child = i == tree.children.len() - 1;
            let child_prefix = if is_last_child {
                format!("{}  ", prefix)
            } else {
                format!("{}│ ", prefix)
            };
            self.display_top_down(child, depth + 1, root_size, &child_prefix);
        }
    }

    fn print_node_bottom_up(&self, tree: &DataTree, root_size: u64, prefix: &str, depth: usize) {
        let formatted_size = self.formatter.format(tree.size);
        let percentage = if root_size > 0 {
            (tree.size as f64 / root_size as f64) * 100.0
        } else {
            0.0
        };

        let bar_width = self.get_bar_width();
        let bar_filled = if root_size > 0 {
            ((tree.size as f64 / root_size as f64) * bar_width as f64) as usize
        } else {
            0
        };
        let bar_empty = bar_width.saturating_sub(bar_filled);

        let bar = format!(
            "{}{}",
            "█".repeat(bar_filled),
            "░".repeat(bar_empty)
        );

        let connector = if depth == 0 {
            "┌─┴".to_string()
        } else if tree.children.is_empty() {
            "┴".to_string()
        } else {
            "├─┴".to_string()
        };

        let full_prefix = format!("{}{}", prefix, connector);

        println!(
            "{:>5} {:<20}│{}│{:>4}%",
            formatted_size, full_prefix, bar, percentage as u32
        );
    }

    fn print_node_top_down(&self, tree: &DataTree, root_size: u64, prefix: &str, _depth: usize) {
        let formatted_size = self.formatter.format(tree.size);
        let percentage = if root_size > 0 {
            (tree.size as f64 / root_size as f64) * 100.0
        } else {
            0.0
        };

        let bar_width = self.get_bar_width();
        let bar_filled = if root_size > 0 {
            ((tree.size as f64 / root_size as f64) * bar_width as f64) as usize
        } else {
            0
        };
        let bar_empty = bar_width.saturating_sub(bar_filled);

        let bar = format!(
            "{}{}",
            "█".repeat(bar_filled),
            "░".repeat(bar_empty)
        );

        let connector = if prefix.is_empty() {
            "┌─".to_string()
        } else {
            "├─".to_string()
        };

        let full_prefix = format!("{}{}", prefix, connector);

        println!(
            "{:>5} {:<20}│{}│{:>4}%",
            formatted_size, full_prefix, bar, percentage as u32
        );
    }

    fn get_bar_width(&self) -> usize {
        if let Some(width) = self.args.total_width {
            width.saturating_sub(40)
        } else if let Some((_, bar_width)) = self.args.column_width {
            bar_width
        } else {
            120
        }
    }
}
