            "░".repeat(bar_empty)
        );

        let connector = if prefix.is_empty() {
            "┌──".to_string()
        } else {
            "├──".to_string()
        };

        let name_part = format!("{}{}{}", prefix, connector, tree.name);

        println!(
            "{:>5} {:<20}│{}│{:>4}%",
            formatted_size, name_part, bar, percentage as u32
        );
    }

    fn get_bar_width(&self) -> usize {
        if let Some(width) = self.args.total_width {
            width.saturating_sub(40)
        } else if let Some((_, bar_width)) = self.args.column_width {
            bar_width
        } else {
            120
        }
    }
