fn handle_normal_operation(args: &Args) {
    let files = if args.files.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.files.clone()
    };

    let mut root_tree = if files.len() == 1 {
        build_tree(&files[0], args)
    } else {
        let mut children = Vec::new();
        for file in &files {
            let child = build_tree(file, args);
            children.push(child);
        }

        // Calculate total size
        let total_size: u64 = children.iter().map(|c| c.size).sum();
        children.sort_by(|a, b| b.size.cmp(&a.size));

        let mut root = DataTree::new(".".to_string(), total_size, children);
