fn build_tree(path: &Path, args: &Args) -> DataTree {
    let name = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| path.to_string_lossy().to_string());

    if !path.exists() {
        if !args.silent_errors {
            eprintln!("Path not found: {}", path.display());
        }
        return DataTree::new(name, 0, vec![]);
    }

    if path.is_file() {
        let size = get_file_size(path, args);
        DataTree::new(name, size, vec![])
    } else {
        build_directory_tree(path, &name, args)
    }
}

fn build_directory_tree(path: &Path, name: &str, args: &Args) -> DataTree {
    let mut children = Vec::new();

    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries {
            if let Ok(entry) = entry {
                let entry_path = entry.path();
                let entry_name = entry_path
                    .file_name()
                    .map(|n| n.to_string_lossy().to_string())
                    .unwrap_or_default();

                if entry_path.is_dir() {
                    let mut child = build_directory_tree(&entry_path, &entry_name, args);
                    child.size = calc_dir_size(&entry_path, args);
                    children.push(child);
                } else {
                    let size = get_file_size(&entry_path, args);
                    children.push(DataTree::new(entry_name, size, vec![]));
                }
            }
        }
    }

    children.sort_by(|a, b| b.size.cmp(&a.size));
    let total_size: u64 = children.iter().map(|c| c.size).sum();

    let mut tree = DataTree::new(name.to_string(), total_size, children);
    tree.sort_children(!args.no_sort);
    tree
}

fn calc_dir_size(path: &Path, args: &Args) -> u64 {
    fn walk_dir(path: &Path, args: &Args) -> u64 {
        let mut size = 0;
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries {
                if let Ok(entry) = entry {
                    let entry_path = entry.path();
                    if entry_path.is_dir() {
                        size += walk_dir(&entry_path, args);
                    } else {
                        size += get_file_size(&entry_path, args);
                    }
                }
            }
        }
        size
    }

    walk_dir(path, args)
}

fn get_file_size(path: &Path, args: &Args) -> u64 {
    match fs::metadata(path) {
        Ok(metadata) => {
            match args.quantity.as_str() {
                "apparent-size" => metadata.len(),
                "block-count" => {
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::MetadataExt;
                        metadata.blocks()
                    }
                    #[cfg(not(unix))]
                    {
                        (metadata.len() + 511) / 512
                    }
                }
                _ => {
                    // block-size
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::MetadataExt;
                        metadata.blocks() * 512
                    }
                    #[cfg(not(unix))]
                    {
                        (metadata.len() + 511) / 512 * 512
                    }
                }
            }
        }
        Err(_) => {
            if !args.silent_errors {
                eprintln!("Failed to get metadata for: {}", path.display());
            }
            0
        }
    }
}
